#include "xml_internal.h"

bool svg_xml_internal_char(uint32_t cp)
{
    return cp == 0x9U || cp == 0xaU || cp == 0xdU ||
           (cp >= 0x20U && cp <= 0xd7ffU) || (cp >= 0xe000U && cp <= 0xfffdU) ||
           (cp >= 0x10000U && cp <= 0x10ffffU);
}

bool svg_xml_internal_utf8_next(const uint8_t *bytes, size_t length, size_t *position, uint32_t *cp)
{
    if (position == NULL || cp == NULL || *position >= length) return false;
    size_t p = *position;
    uint8_t a = bytes[p];
    size_t count = 0;
    uint32_t value = 0;
    if (a < 0x80U) { count = 1; value = a; }
    else if (a >= 0xc2U && a <= 0xdfU) { count = 2; value = (uint32_t)(a & 0x1fU); }
    else if (a >= 0xe0U && a <= 0xefU) { count = 3; value = (uint32_t)(a & 0x0fU); }
    else if (a >= 0xf0U && a <= 0xf4U) { count = 4; value = (uint32_t)(a & 0x07U); }
    else return false;
    if (count > length - p) return false;
    for (size_t i = 1; i < count; ++i) {
        uint8_t b = bytes[p + i];
        if ((b & 0xc0U) != 0x80U) return false;
        value = (value << 6U) | (uint32_t)(b & 0x3fU);
    }
    if ((count == 3 && ((a == 0xe0U && bytes[p + 1] < 0xa0U) ||
                        (a == 0xedU && bytes[p + 1] >= 0xa0U))) ||
        (count == 4 && ((a == 0xf0U && bytes[p + 1] < 0x90U) ||
                        (a == 0xf4U && bytes[p + 1] >= 0x90U))) ||
        value > 0x10ffffU || (value >= 0xd800U && value <= 0xdfffU)) return false;
    *position = p + count;
    *cp = value;
    return true;
}

bool svg_xml_internal_name_start(uint32_t c)
{
    return c == ':' || c == '_' || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
           (c >= 0xc0U && c <= 0xd6U) || (c >= 0xd8U && c <= 0xf6U) ||
           (c >= 0xf8U && c <= 0x2ffU) || (c >= 0x370U && c <= 0x37dU) ||
           (c >= 0x37fU && c <= 0x1fffU) || (c >= 0x200cU && c <= 0x200dU) ||
           (c >= 0x2070U && c <= 0x218fU) || (c >= 0x2c00U && c <= 0x2fefU) ||
           (c >= 0x3001U && c <= 0xd7ffU) || (c >= 0xf900U && c <= 0xfdcfU) ||
           (c >= 0xfdf0U && c <= 0xfffdU) || (c >= 0x10000U && c <= 0xeffffU);
}

bool svg_xml_internal_name_char(uint32_t c)
{
    return svg_xml_internal_name_start(c) || c == '-' || c == '.' || (c >= '0' && c <= '9') ||
           c == 0xb7U || (c >= 0x300U && c <= 0x36fU) || (c >= 0x203fU && c <= 0x2040U);
}

bool svg_xml_internal_whitespace(uint8_t c)
{
    return c == 0x20U || c == 0x9U || c == 0xaU || c == 0xdU;
}

#ifndef VEXEL_SVG_XML_READER_H
#define VEXEL_SVG_XML_READER_H

#include "xml_tokenizer.h"

typedef struct svg_xml_reader svg_xml_reader;

typedef enum svg_xml_reader_status {
    SVG_XML_READER_OK = 0,
    SVG_XML_READER_COMPLETE,
    SVG_XML_READER_INVALID,
    SVG_XML_READER_LIMIT,
    SVG_XML_READER_MALFORMED
} svg_xml_reader_status;

typedef struct svg_xml_reader_tag {
    svg_xml_token_kind kind;
    svg_xml_span source;
    svg_xml_span name;
    size_t attribute_count;
} svg_xml_reader_tag;

typedef struct svg_xml_reader_progress {
    size_t bytes_read;
    size_t source_bytes;
    svg_xml_diagnostic diagnostic;
    bool complete;
} svg_xml_reader_progress;

typedef bool (*svg_xml_reader_tag_fn)(void *context, const svg_xml_reader_tag *tag);

/* Borrows immutable source bytes through destroy; no content is copied. */
svg_xml_reader_status svg_xml_reader_start(base_bytes source, svg_xml_reader **out_reader);
/* Advances at most byte_budget bytes (hard capped at 64 KiB), emitting complete tags. */
svg_xml_reader_status svg_xml_reader_step(svg_xml_reader *reader, size_t byte_budget,
    svg_xml_reader_tag_fn on_tag, void *context);
svg_xml_reader_progress svg_xml_reader_get_progress(const svg_xml_reader *reader);
void svg_xml_reader_destroy(svg_xml_reader *reader);

#endif
#include "xml_reader.h"
#include "xml_doctype.h"

#include <stdlib.h>
#include <string.h>

#define XML_READER_MAX_SOURCE_BYTES (1024U * 1024U * 1024U)
#define XML_READER_MAX_STEP_BYTES (64U * 1024U)

typedef enum reader_mode { MODE_TEXT, MODE_PROBE, MODE_TAG, MODE_COMMENT, MODE_CDATA, MODE_PI, MODE_DOCTYPE } reader_mode;
typedef enum probe_kind { PROBE_NONE, PROBE_COMMENT, PROBE_CDATA, PROBE_DOCTYPE } probe_kind;

struct svg_xml_reader {
    base_bytes source;
    size_t bytes_read;
    size_t token_start;
    size_t name_offset;
    size_t name_length;
    size_t attribute_count;
    size_t probe_position;
    reader_mode mode;
    probe_kind probe;
    bool closing;
    bool name_complete;
    bool in_quote;
    bool pending_slash;
    bool self_closing;
    uint8_t quote;
    bool complete;
    bool element_seen;
    bool doctype_seen;
    xml_doctype_state doctype;
    svg_xml_diagnostic diagnostic;
};

static bool is_name_byte(uint8_t c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9') || c >= 0x80U || c == '_' || c == '-' ||
           c == '.' || c == ':';
}

static void reader_fail(svg_xml_reader *r, svg_xml_error error, size_t offset)
{
    if (r->diagnostic.category == SVG_XML_ERROR_NONE) {
        r->diagnostic.category = error;
        r->diagnostic.offset = offset <= r->source.len ? offset : r->source.len;
    }
}

static bool emit_tag(svg_xml_reader *r, size_t end, svg_xml_reader_tag_fn callback,
                     void *context)
{
    if (r->name_length == 0U || r->name_length > 4096U) {
        reader_fail(r, SVG_XML_ERROR_INVALID_NAME, r->name_offset);
        return false;
    }
    if (!r->closing) r->element_seen = true;
    if (callback != NULL) {
        svg_xml_reader_tag tag = {
            r->closing ? SVG_XML_TOKEN_END_ELEMENT :
            r->self_closing ? SVG_XML_TOKEN_EMPTY_ELEMENT : SVG_XML_TOKEN_START_ELEMENT,
            {r->token_start, end - r->token_start},
            {r->name_offset, r->name_length}, r->attribute_count
        };
        if (!callback(context, &tag)) {
            reader_fail(r, SVG_XML_ERROR_OUTPUT_EXHAUSTED, r->token_start);
            return false;
        }
    }
    r->mode = MODE_TEXT;
    return true;
}

svg_xml_reader_status svg_xml_reader_start(base_bytes source, svg_xml_reader **out)
{
    if (out == NULL) return SVG_XML_READER_INVALID;
    *out = NULL;
    if (source.len > XML_READER_MAX_SOURCE_BYTES) return SVG_XML_READER_LIMIT;
    if (!base_bytes_valid(source)) return SVG_XML_READER_INVALID;
    svg_xml_reader *r = calloc(1U, sizeof(*r));
    if (r == NULL) return SVG_XML_READER_INVALID;
    r->source = source;
    r->mode = MODE_TEXT;
    *out = r;
    return SVG_XML_READER_OK;
}

svg_xml_reader_status svg_xml_reader_step(svg_xml_reader *r, size_t byte_budget,
    svg_xml_reader_tag_fn callback, void *context)
{
    if (r == NULL || byte_budget == 0U) return SVG_XML_READER_INVALID;
    if (r->diagnostic.category != SVG_XML_ERROR_NONE) return SVG_XML_READER_MALFORMED;
    if (r->complete) return SVG_XML_READER_COMPLETE;
    if (byte_budget > XML_READER_MAX_STEP_BYTES) byte_budget = XML_READER_MAX_STEP_BYTES;
    size_t end = r->bytes_read + byte_budget;
    if (end < r->bytes_read || end > r->source.len) end = r->source.len;
    while (r->bytes_read < end && r->diagnostic.category == SVG_XML_ERROR_NONE) {
        size_t at = r->bytes_read;
        uint8_t c = r->source.ptr[at];
        if (r->mode == MODE_TEXT) {
            if (c == '<') {
                r->mode = MODE_PROBE;
                r->token_start = at;
                r->probe = PROBE_NONE;
                r->probe_position = 0U;
            }
        } else if (r->mode == MODE_PROBE) {
            if (r->probe_position == 0U) {
                if (c == '?') r->mode = MODE_PI;
                else if (c == '/') {
                    r->mode = MODE_TAG; r->closing = true;
                    r->name_offset = at + 1U; r->name_length = 0U;
                    r->attribute_count = 0U;
                    r->name_complete = false; r->pending_slash = false;
                } else if (c == '!') r->probe_position = 1U;
                else if (is_name_byte(c)) {
                    r->mode = MODE_TAG; r->closing = false;
                    r->name_offset = at; r->name_length = 1U;
                    r->attribute_count = 0U;
                    r->name_complete = false; r->pending_slash = false;
                } else reader_fail(r, SVG_XML_ERROR_INVALID_NAME, at);
            } else if (r->probe == PROBE_NONE) {
                if (c == '-') { r->probe = PROBE_COMMENT; r->probe_position = 1U; }
                else if (c == '[') { r->probe = PROBE_CDATA; r->probe_position = 1U; }
                else if (c == 'D' && !r->doctype_seen && !r->element_seen) {
                    r->probe = PROBE_DOCTYPE; r->probe_position = 1U;
                }
                else reader_fail(r, SVG_XML_ERROR_UNSUPPORTED_DTD, r->token_start);
            } else if (r->probe == PROBE_COMMENT) {
                if (c != '-') reader_fail(r, SVG_XML_ERROR_MALFORMED_SYNTAX, r->token_start);
                else r->mode = MODE_COMMENT;
            } else if (r->probe == PROBE_DOCTYPE) {
                static const char tail[] = "OCTYPE";
                if (c != (uint8_t)tail[r->probe_position - 1U])
                    reader_fail(r, SVG_XML_ERROR_UNSUPPORTED_DTD, r->token_start);
                else if (r->probe_position == sizeof(tail) - 1U) {
                    r->mode = MODE_DOCTYPE; r->doctype_seen = true;
                    r->doctype = (xml_doctype_state){0};
                } else ++r->probe_position;
            } else {
                static const char tail[] = "CDATA[";
                if (r->probe_position > sizeof(tail) - 1U ||
                    c != (uint8_t)tail[r->probe_position - 1U])
                    reader_fail(r, SVG_XML_ERROR_MALFORMED_SYNTAX, r->token_start);
                else if (r->probe_position == sizeof(tail) - 1U) r->mode = MODE_CDATA;
                else ++r->probe_position;
            }
        } else if (r->mode == MODE_TAG) {
            if (!r->name_complete) {
                if (is_name_byte(c)) {
                    if (r->name_length == 4096U) reader_fail(r, SVG_XML_ERROR_INVALID_NAME, r->name_offset);
                    else ++r->name_length;
                    ++r->bytes_read;
                    continue;
                }
                if (r->name_length == 0U) reader_fail(r, SVG_XML_ERROR_INVALID_NAME, r->name_offset);
                else r->name_complete = true;
            }
            if (r->in_quote) {
                if (c == r->quote) r->in_quote = false;
            } else if (c == '\'' || c == '"') {
                r->in_quote = true; r->quote = c;
                ++r->attribute_count;
            } else if (c == '/') {
                r->pending_slash = true;
            } else if (c == '>') {
                r->self_closing = r->pending_slash;
                if (!emit_tag(r, at + 1U, callback, context)) break;
            } else r->pending_slash = false;
        } else if (r->mode == MODE_COMMENT && c == '>' && at >= 2U &&
                   r->source.ptr[at - 1U] == '-' && r->source.ptr[at - 2U] == '-') {
            r->mode = MODE_TEXT;
        } else if (r->mode == MODE_CDATA && c == '>' && at >= 2U &&
                   r->source.ptr[at - 1U] == ']' && r->source.ptr[at - 2U] == ']') {
            r->mode = MODE_TEXT;
        } else if (r->mode == MODE_DOCTYPE) {
            xml_doctype_result d = xml_doctype_step(&r->doctype, c);
            if (d == XML_DOCTYPE_BAD) reader_fail(r, SVG_XML_ERROR_MALFORMED_SYNTAX, at);
            else if (d == XML_DOCTYPE_DONE) r->mode = MODE_TEXT;
        } else if (r->mode == MODE_PI && c == '>' && at > 0U && r->source.ptr[at - 1U] == '?') {
            r->mode = MODE_TEXT;
        }
        ++r->bytes_read;
    }
    if (r->diagnostic.category != SVG_XML_ERROR_NONE) return SVG_XML_READER_MALFORMED;
    if (r->bytes_read == r->source.len) {
        if (r->mode != MODE_TEXT) reader_fail(r, SVG_XML_ERROR_INCOMPLETE_DOCUMENT, r->source.len);
        else r->complete = true;
    }
    return r->diagnostic.category == SVG_XML_ERROR_NONE ?
        (r->complete ? SVG_XML_READER_COMPLETE : SVG_XML_READER_OK) : SVG_XML_READER_MALFORMED;
}

svg_xml_reader_progress svg_xml_reader_get_progress(const svg_xml_reader *r)
{
    svg_xml_reader_progress p = {0};
    if (r == NULL) return p;
    p.bytes_read = r->bytes_read; p.source_bytes = r->source.len;
    p.diagnostic = r->diagnostic; p.complete = r->complete;
    return p;
}

void svg_xml_reader_destroy(svg_xml_reader *r) { free(r); }
